import ee, math, sys
ee.Initialize(project='earthsense-436113')

# ----------------- Helpers -----------------
def get_country_geom(name):
    fc = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017').filter(
        ee.Filter.equals('country_na', name)
    )
    return ee.Feature(fc.first()).geometry()

def prep_vi(img):
    ndvi = img.select('NDVI').multiply(0.0001).rename('ndvi')
    hasQA = img.bandNames().contains('SummaryQA')
    qa_mask = ee.Image(ee.Algorithms.If(hasQA, img.select('SummaryQA').lte(1), ee.Image(1)))
    return ndvi.updateMask(qa_mask)

def prep_vi_monthly(img):
    # Monthly product typically lacks SummaryQA; just scale
    return img.select('NDVI').multiply(0.0001).rename('ndvi')

def safe_get(x):
    try:
        return x.getInfo()
    except Exception:
        return None

def count_pixels(img, geom, scale=3000):
    valid = img.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('ndvi')
    total = ee.Image.constant(1).rename('ndvi').reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('ndvi')
    return valid, total

def region_mean(img, geom, scale=3000):
    return img.reduceRegion(
        reducer=ee.Reducer.mean(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('ndvi')

def valid_number(x):
    return (x is not None) and isinstance(x, (int, float)) and (not math.isnan(x)) and (-0.5 <= x <= 1.0)

# ----------------- Geometry -----------------
nam_geom = get_country_geom('Namibia')
zwe_geom = get_country_geom('Zimbabwe')

# ----------------- Try Products in Order -----------------
attempts = [
    {
        'name': 'MOD13Q1+MYD13Q1 v061 (250m, 16-day)',
        'collections': [
            ee.ImageCollection('MODIS/061/MOD13Q1').map(prep_vi),
            ee.ImageCollection('MODIS/061/MYD13Q1').map(prep_vi)
        ],
        'monthly': False
    },
    {
        'name': 'MOD13A2 v061 (Terra 1km, 16-day)',
        'collections': [ee.ImageCollection('MODIS/061/MOD13A2').map(prep_vi)],
        'monthly': False
    },
    {
        'name': 'MOD13C2 v061 (Terra monthly, 0.05°)',
        'collections': [ee.ImageCollection('MODIS/061/MOD13C2').map(prep_vi_monthly)],
        'monthly': True
    }
]

used_name = None
n2019 = 0
nclim = 0
img_2019 = None
clim_img = None

for att in attempts:
    try:
        col = att['collections'][0]
        if len(att['collections']) > 1:
            for c in att['collections'][1:]:
                col = col.merge(c)

        if att['monthly']:
            col_2019 = col.filterDate('2019-02-01', '2019-03-01').filter(
                ee.Filter.calendarRange(2, 2, 'month')
            )
        else:
            # Prefer the exact week; if empty, use full February
            week = col.filterDate('2019-02-21', '2019-02-28')
            n_week = safe_get(week.size())
            if n_week is None:
                continue
            if n_week == 0:
                col_2019 = col.filterDate('2019-02-01', '2019-03-01').filter(
                    ee.Filter.calendarRange(2, 2, 'month')
                )
            else:
                col_2019 = week

        n2019 = safe_get(col_2019.size())
        if n2019 is None or n2019 == 0:
            continue

        img_2019 = col_2019.mean()

        clim_col = col.filterDate('2003-01-01', '2018-01-01').filter(
            ee.Filter.calendarRange(2, 2, 'month')
        )
        nclim = safe_get(clim_col.size())
        if nclim is None or nclim == 0:
            continue

        clim_img = clim_col.mean()
        used_name = att['name']
        break
    except Exception:
        continue

if used_name is None or img_2019 is None or clim_img is None:
    print("2019 images: 0")
    print("C1")
    sys.exit(0)

# ----------------- Pixel Counts (2019) -----------------
v_nam_2019, t_nam = count_pixels(img_2019, nam_geom, scale=3000)
v_zwe_2019, t_zwe = count_pixels(img_2019, zwe_geom, scale=3000)
v_nam_2019, t_nam = safe_get(v_nam_2019), safe_get(t_nam)
v_zwe_2019, t_zwe = safe_get(v_zwe_2019), safe_get(t_zwe)

if any(x is None for x in [v_nam_2019, t_nam, v_zwe_2019, t_zwe]):
    print("Pixel count failure.")
    print("D")
    sys.exit(0)

if v_nam_2019 == 0 or v_zwe_2019 == 0:
    print(f"2019 images: {n2019}")
    print("No valid pixels after masking.")
    print("C2")
    sys.exit(0)

cloud_nam = 100.0 * max(0.0, 1.0 - (float(v_nam_2019) / float(t_nam)))
cloud_zwe = 100.0 * max(0.0, 1.0 - (float(v_zwe_2019) / float(t_zwe)))

# ----------------- Means -----------------
m2019_nam = safe_get(region_mean(img_2019, nam_geom, scale=3000))
m2019_zwe = safe_get(region_mean(img_2019, zwe_geom, scale=3000))
mclim_nam = safe_get(region_mean(clim_img, nam_geom, scale=3000))
mclim_zwe = safe_get(region_mean(clim_img, zwe_geom, scale=3000))

vals = [m2019_nam, m2019_zwe, mclim_nam, mclim_zwe]
if any(not valid_number(v) for v in vals):
    print("Mean NDVI invalid or None.")
    print("C3")
    sys.exit(0)

anom_nam = m2019_nam - mclim_nam
anom_zwe = m2019_zwe - mclim_zwe
if any(math.isnan(v) for v in [anom_nam, anom_zwe]):
    print("Anomaly calculation failed.")
    print("C3")
    sys.exit(0)

# ----------------- Prints (<=20 lines) -----------------
print(f"Dataset: {used_name}")
print(f"2019 period images: {n2019}")
print(f"Climatology Feb 2003-2017 images: {nclim}")
print(f"Namibia valid pixels: {v_nam_2019}/{t_nam} (cloud%≈{cloud_nam:.1f})")
print(f"Zimbabwe valid pixels: {v_zwe_2019}/{t_zwe} (cloud%≈{cloud_zwe:.1f})")
print(f"Namibia NDVI 2019: {m2019_nam:.3f}, Clim: {mclim_nam:.3f}, Anom: {anom_nam:.3f}")
print(f"Zimbabwe NDVI 2019: {m2019_zwe:.3f}, Clim: {mclim_zwe:.3f}, Anom: {anom_zwe:.3f}")
print("A" if anom_nam < anom_zwe else "B")

